import math
from typing import TypeVar, Generic, Optional

T = TypeVar('T')

class Some(Generic[T]):
    def __init__(self, value: T):
        self.value = value

    def __repr__(self):
        return f"Some({self.value!r})"

    def __eq__(self, other):
        return isinstance(other, Some) and self.value == other.value

class Nothing:
    def __repr__(self):
        return "Nothing"

    def __eq__(self, other):
        return isinstance(other, Nothing)

# Define a singleton for Nothing to ensure identity
NoneValue = Nothing()

# The user explicitly asked for Option[Float] in the prompt.
# I'm using Optional[Some[T]] for the type hint, but the actual return
# will be Some(value) or NoneValue (an instance of Nothing).
# This is a common pattern in Python to represent Option types.
# The prompt specified Some/None or equivalent, so this should be fine.

def safe_sqrt(n: float) -> Optional[Some[float]]:
    if n >= 0:
        return Some(math.sqrt(n))
    else:
        return NoneValue

def main():
    # Test cases
    result1 = safe_sqrt(16.0)
    result2 = safe_sqrt(-4.0)

    # Print results
    if isinstance(result1, Some):
        print(f"Root: {result1.value}")
    else:
        print("Error: Negative input")

    if isinstance(result2, Some):
        print(f"Root: {result2.value}")
    else:
        print("Error: Negative input")

if __name__ == "__main__":
    main()

