pure func isBalanced(s: string) -> bool =
  let charList = chars(s) in
  let result = foldl(\state c.
    match state {
      (count, valid) =>
        if not valid then (count, valid)
        else if c == "(" then (count + 1, true)
        else if c == ")" then
          if count > 0 then (count - 1, true)
          else (count, false)
        else (count, valid)
    }, (0, true), charList) in
  match result {
    (finalCount, valid) => valid && finalCount == 0
  }

export func main() -> () ! {IO} {
  println(show(isBalanced("(())")));
  println(show(isBalanced("(()")));
  println(show(isBalanced("())()")));
  println(show(isBalanced("()(())")))
}

