def isBalanced(s: str) -> bool:
    counter = 0
    for ch in s:
        if ch == '(':
            counter += 1
        elif ch == ')':
            counter -= 1
        if counter < 0:
            return False
    return counter == 0


def main():
    tests = ["(())", "(()", "())()", "()(())"]
    for s in tests:
        print("true" if isBalanced(s) else "false")


if __name__ == "__main__":
    main()

