from dataclasses import dataclass
from typing import Union, Optional


@dataclass
class Leaf:
    value: int


@dataclass
class Branch:
    left: Optional[Union["Branch", Leaf]]
    value: int
    right: Optional[Union["Branch", Leaf]]


Tree = Union[Branch, Leaf]


def treeSum(tree: Optional[Tree]) -> int:
    if tree is None:
        return 0
    if isinstance(tree, Leaf):
        return tree.value
    return treeSum(tree.left) + tree.value + treeSum(tree.right)


def main():
    tree = Branch(
        left=Branch(
            left=Leaf(1),
            value=3,
            right=Leaf(4),
        ),
        value=5,
        right=Branch(
            left=None,
            value=8,
            right=Leaf(10),
        ),
    )
    print(treeSum(tree))


if __name__ == "__main__":
    main()

