module benchmark/solution

import std/fs (readFile, writeFile)
import std/json (decode, getString, getInt, getArray)
import std/string (split)
import std/list (length as listLength)
import std/option (Option, Some, None)
import std/result (Result, Ok, Err)

pure func countDots(s: string) -> int {
  let parts = split(s, ".");
  listLength(parts) - 1
}

pure func validatePort(port: int) -> bool =
  port >= 1024 && port <= 65535

pure func validateVersion(version: string) -> bool =
  countDots(version) == 2

pure func validateFeatures(features: [Json]) -> bool =
  listLength(features) > 0

func loadAndValidate(path: string) -> Result[string, string] ! {FS} {
  let content = readFile(path);
  match decode(content) {
    Err(e) => Err("JSON parse error: " ++ e),
    Ok(obj) => {
      match getString(obj, "app_name") {
        None => Err("Missing app_name"),
        Some(appName) => {
          match getString(obj, "version") {
            None => Err("Missing version"),
            Some(version) => {
              match getInt(obj, "port") {
                None => Err("Missing or invalid port"),
                Some(port) => {
                  match getArray(obj, "features") {
                    None => Err("Missing features"),
                    Some(features) => {
                      if not validatePort(port) then
                        Err("Port must be between 1024 and 65535")
                      else if not validateVersion(version) then
                        Err("Version must be in X.Y.Z format")
                      else if not validateFeatures(features) then
                        Err("Features list must not be empty")
                      else
                        Ok("Loaded " ++ appName ++ " v" ++ version ++ " on port " ++ show(port) ++ " with " ++ show(listLength(features)) ++ " features")
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

export func main() -> () ! {IO, FS} {
  let configJson = "{\"app_name\":\"MyApp\",\"version\":\"1.0.0\",\"port\":8080,\"features\":[\"logging\",\"auth\",\"api\"]}";
  writeFile("app_config.json", configJson);
  match loadAndValidate("app_config.json") {
    Ok(msg) => println(msg),
    Err(e) => println("Error: " ++ e)
  }
}

