from __future__ import annotations
from dataclasses import dataclass
from typing import Optional


@dataclass
class Leaf:
    pass


@dataclass
class Node:
    value: int
    left: 'BST'
    right: 'BST'


BST = Leaf | Node


def insert(tree: BST, value: int) -> BST:
    if isinstance(tree, Leaf):
        return Node(value, Leaf(), Leaf())
    elif value < tree.value:
        return Node(tree.value, insert(tree.left, value), tree.right)
    elif value > tree.value:
        return Node(tree.value, tree.left, insert(tree.right, value))
    else:
        return tree


def contains(tree: BST, value: int) -> bool:
    if isinstance(tree, Leaf):
        return False
    elif value == tree.value:
        return True
    elif value < tree.value:
        return contains(tree.left, value)
    else:
        return contains(tree.right, value)


def size(tree: BST) -> int:
    if isinstance(tree, Leaf):
        return 0
    return 1 + size(tree.left) + size(tree.right)


def isBST(tree: BST, lower: int, upper: int) -> bool:
    if isinstance(tree, Leaf):
        return True
    if tree.value <= lower or tree.value >= upper:
        return False
    return isBST(tree.left, lower, tree.value) and isBST(tree.right, tree.value, upper)


def insertPreservesBST(value: int) -> bool:
    """Proof: inserting a value into a valid BST preserves the BST property."""
    tree = Leaf()
    for v in [10, 5, 15, 3, 7]:
        tree = insert(tree, v)
    before = isBST(tree, -999999, 999999)
    after_tree = insert(tree, value)
    after = isBST(after_tree, -999999, 999999)
    return before and after


def insertThenFind(value: int) -> bool:
    """Proof: after inserting a value, contains must return True."""
    tree = Leaf()
    for v in [10, 5, 15, 3, 7]:
        tree = insert(tree, v)
    tree = insert(tree, value)
    return contains(tree, value)


def main():
    t = insert(insert(insert(Leaf(), 5), 3), 7)
    print(size(t))
    print(contains(t, 3))
    print(contains(t, 4))
    print(isBST(t, -999999, 999999))
    print(insertPreservesBST(42))
    print(insertThenFind(42))


if __name__ == "__main__":
    main()

