def encode(s: str) -> str:
    if not s:
        return ""

    result = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            result.append(f"{count}{s[i - 1]}")
            count = 1

    result.append(f"{count}{s[-1]}")
    return "".join(result)


def decode(s: str) -> str:
    if not s:
        return ""

    result = []
    i = 0

    while i < len(s):
        count_str = []
        while i < len(s) and s[i].isdigit():
            count_str.append(s[i])
            i += 1

        if i < len(s) and count_str:
            count = int("".join(count_str))
            result.append(s[i] * count)
            i += 1

    return "".join(result)


def roundtrip(s: str) -> bool:
    return decode(encode(s)) == s


def singleCharEncode(c: str) -> str:
    return encode(c)


def main():
    print(encode("aaabbc"))
    print(encode("xyz"))
    print(decode("3a2b1c"))
    print(decode("1x1y1z"))
    print(roundtrip("hello"))
    print(singleCharEncode("q"))


if __name__ == "__main__":
    main()

