from __future__ import annotations
from dataclasses import dataclass
from typing import Union


# ADT definition for sorted integer sets
class SNil:
    """Empty sorted integer set."""
    pass


@dataclass
class SCons:
    """Non-empty sorted integer set node."""
    head: int
    tail: SortedSet

    def __init__(self, head: int, tail: 'SortedSet'):
        self.head = head
        self.tail = tail


SortedSet = Union[SNil, SCons]


def sLength(s: SortedSet) -> int:
    """Return the number of elements in the sorted set."""
    if isinstance(s, SNil):
        return 0
    return 1 + sLength(s.tail)


def toStr(s: SortedSet) -> str:
    """Convert sorted set to string representation."""
    elements = []
    current = s
    while isinstance(current, SCons):
        elements.append(str(current.head))
        current = current.tail
    return "{" + ", ".join(elements) + "}"


def isSorted(s: SortedSet) -> bool:
    """Check if the set is sorted in ascending order with no duplicates."""
    if isinstance(s, SNil):
        return True
    if isinstance(s.tail, SNil):
        return True
    if s.head >= s.tail.head:
        return False
    return isSorted(s.tail)


def sMerge(a: SortedSet, b: SortedSet) -> SortedSet:
    """Compute the union of two sorted sets, preserving sorted + no-duplicates invariant."""
    if isinstance(a, SNil):
        return b
    if isinstance(b, SNil):
        return a
    if a.head < b.head:
        return SCons(a.head, sMerge(a.tail, b))
    elif a.head > b.head:
        return SCons(b.head, sMerge(a, b.tail))
    else:
        # Equal elements: include once, advance both
        return SCons(a.head, sMerge(a.tail, b.tail))


def sIntersect(a: SortedSet, b: SortedSet) -> SortedSet:
    """Compute the intersection of two sorted sets, preserving sorted + no-duplicates invariant."""
    if isinstance(a, SNil) or isinstance(b, SNil):
        return SNil()
    if a.head < b.head:
        return sIntersect(a.tail, b)
    elif a.head > b.head:
        return sIntersect(a, b.tail)
    else:
        # Equal elements: include in intersection
        return SCons(a.head, sIntersect(a.tail, b.tail))


def mergePreservesSorted(a: SortedSet, b: SortedSet) -> bool:
    """Proof that sMerge preserves the sorted invariant."""
    return isSorted(sMerge(a, b))


def inclusionExclusion(a: SortedSet, b: SortedSet) -> bool:
    """Proof of inclusion-exclusion principle: |A∪B| + |A∩B| == |A| + |B|."""
    union_size = sLength(sMerge(a, b))
    intersection_size = sLength(sIntersect(a, b))
    a_size = sLength(a)
    b_size = sLength(b)
    return union_size + intersection_size == a_size + b_size


def main():
    a = SCons(1, SCons(3, SCons(5, SNil())))
    b = SCons(2, SCons(3, SCons(4, SNil())))

    print(toStr(sMerge(SCons(1, SCons(3, SCons(5, SNil()))), SCons(2, SCons(3, SCons(4, SNil()))))))
    print(toStr(sIntersect(SCons(1, SCons(3, SCons(5, SNil()))), SCons(2, SCons(3, SCons(4, SNil()))))))
    print(sLength(sMerge(SCons(1, SCons(3, SCons(5, SNil()))), SCons(2, SCons(3, SCons(4, SNil()))))))
    print(isSorted(sMerge(SCons(1, SCons(3, SCons(5, SNil()))), SCons(2, SCons(3, SCons(4, SNil()))))))
    print(mergePreservesSorted(SCons(1, SCons(3, SCons(5, SNil()))), SCons(2, SCons(3, SCons(4, SNil())))))
    print(inclusionExclusion(SCons(1, SCons(3, SCons(5, SNil()))), SCons(2, SCons(3, SCons(4, SNil())))))


if __name__ == "__main__":
    main()

