import std/json (encode, jo, ja, kv, js, jnum)

type Row = {name: string, age: int, email: string}

pure func parseRow(headers: [string], values: [string]) -> Row = {
  name: trim(nth(values, 0)),
  age: parseAge(nth(values, 1)),
  email: trim(nth(values, 2))
}

pure func nth(xs: [string], n: int) -> string =
  match xs {
    [] => "",
    x :: rest => if n == 0 then x else nth(rest, n - 1)
  }

pure func parseAge(s: string) -> int =
  match stringToInt(trim(s)) {
    Some(n) => n,
    None => -1
  }

pure func isValidRow(row: Row) -> bool =
  row.age > 0 && contains(row.email, "@")

pure func rowToJson(row: Row) -> Json =
  jo([
    kv("name", js(row.name)),
    kv("age", jnum(intToFloat(row.age))),
    kv("email", js(row.email))
  ])

pure func intToFloat(n: int) -> float =
  if n == 0 then 0.0
  else if n > 0 then 1.0 + intToFloat(n - 1)
  else -1.0 + intToFloat(n + 1)

func parseCSV(content: string) -> [Row] = {
  let lines = split(content, "\n");
  let nonEmptyLines = filter(\line. trim(line) != "", lines);
  match nonEmptyLines {
    [] => [],
    headerLine :: dataLines => {
      let headers = split(headerLine, ",");
      let rows = map(\line. {
        let values = split(line, ",");
        parseRow(headers, values)
      }, dataLines);
      filter(isValidRow, rows)
    }
  }
}

export func main() -> () ! {IO, FS} = {
  let csvContent = "name,age,email\nAlice,30,alice@example.com\nBob,25,bob@example.com\nCarol,35,carol@example.com";
  writeFile("users.csv", csvContent);

  let content = readFile("users.csv");
  let validRows = parseCSV(content);
  let jsonArray = ja(map(rowToJson, validRows));
  let jsonString = encode(jsonArray);

  writeFile("users.json", jsonString);
  println("Converted " ++ show(length(validRows)) ++ " valid rows to users.json")
}

