import csv
import json
from pathlib import Path

def validate_row(row: dict) -> bool:
    try:
        age = int(row["age"])
        if age <= 0:
            return False
    except (ValueError, KeyError):
        return False
    if "@" not in row.get("email", ""):
        return False
    return True

def main():
    base = Path(__file__).parent
    csv_path = base / "users.csv"
    json_path = base / "users.json"

    csv_path.write_text(
        "name,age,email\n"
        "Alice,30,alice@example.com\n"
        "Bob,25,bob@example.com\n"
        "Carol,35,carol@example.com\n"
    )

    valid_rows = []
    with csv_path.open(newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            if validate_row(row):
                valid_rows.append({
                    "name": row["name"],
                    "age": int(row["age"]),
                    "email": row["email"],
                })

    json_path.write_text(json.dumps(valid_rows, indent=2))
    print(f"Converted {len(valid_rows)} valid rows to users.json")

if __name__ == "__main__":
    main()

