from typing import Annotated
from dataclasses import dataclass


@dataclass(frozen=True)
class IOEffect:
    """Marker for functions with IO side effects."""
    pass


@dataclass(frozen=True)
class FSEffect:
    """Marker for functions with filesystem side effects."""
    pass


IO = IOEffect()
FS = FSEffect()


def effect(*effects):
    """Decorator to mark functions with explicit effects."""
    def decorator(func):
        func.__effects__ = effects
        return func
    return decorator


def computeSum(a: int, b: int) -> int:
    return a + b


@effect(IO)
def printSum(a: int, b: int) -> Annotated[None, IOEffect]:
    result = computeSum(a, b)
    print(f"Sum: {result}")


@effect(IO, FS)
def logToFile(filename: str, message: str) -> Annotated[None, IOEffect, FSEffect]:
    with open(filename, "w") as f:
        f.write(message + "\n")


def main():
    result = computeSum(10, 20)
    printSum(10, 20)
    logToFile("output.txt", "Sum was 30")
