import sys
from pathlib import Path
from typing import List, Tuple, Set
from collections import defaultdict, deque


def parse_input(lines: List[str]) -> Tuple[dict, List[Tuple[int, int]]]:
    rules = defaultdict(set)
    updates = []

    reading_rules = True
    for line in lines:
        line = line.strip()
        if not line:
            reading_rules = False
            continue

        if reading_rules:
            before, after = map(int, line.split('|'))
            rules[before].add(after)
        else:
            update = list(map(int, line.split(',')))
            updates.append(update)

    return rules, updates


def is_valid_order(update: List[int], rules: dict) -> bool:
    position = {page: i for i, page in enumerate(update)}

    for i, page in enumerate(update):
        if page in rules:
            for must_come_after in rules[page]:
                if must_come_after in position:
                    if position[must_come_after] < i:
                        return False

    return True


def topological_sort(pages: List[int], rules: dict) -> List[int]:
    page_set = set(pages)
    graph = defaultdict(list)
    in_degree = {page: 0 for page in pages}

    for page in pages:
        if page in rules:
            for after in rules[page]:
                if after in page_set:
                    graph[page].append(after)
                    in_degree[after] += 1

    queue = deque([page for page in pages if in_degree[page] == 0])
    result = []

    while queue:
        node = queue.popleft()
        result.append(node)

        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    return result


def solve_part1(rules: dict, updates: List[List[int]]) -> int:
    total = 0
    for update in updates:
        if is_valid_order(update, rules):
            middle_idx = len(update) // 2
            total += update[middle_idx]
    return total


def solve_part2(rules: dict, updates: List[List[int]]) -> int:
    total = 0
    for update in updates:
        if not is_valid_order(update, rules):
            sorted_update = topological_sort(update, rules)
            middle_idx = len(sorted_update) // 2
            total += sorted_update[middle_idx]
    return total


def main():
    if len(sys.argv) > 1:
        input_file = Path(sys.argv[1])
        lines = input_file.read_text().splitlines()
    else:
        lines = sys.stdin.read().splitlines()

    rules, updates = parse_input(lines)

    part1_result = solve_part1(rules, updates)
    print(f"Part 1: {part1_result}")

    part2_result = solve_part2(rules, updates)
    print(f"Part 2: {part2_result}")


if __name__ == "__main__":
    main()

