module solution

import std/json (decode, getString, getNumber, asArray)
import std/list (map, filter, forEachE, flatMap)
import std/option (Option, Some, None)
import std/result (Result, Ok, Err)

-- Define a type for the processed order information
type OrderInfo = {item: string, total: float}

-- Pure function to parse a single JSON order and calculate its total.
-- Returns a list of OrderInfo (either one element or empty) to be used with flatMap.
pure func parseAndCalculateForFlatMap(orderJson: Json) -> [OrderInfo] =
  match getString(orderJson, "item") {
    Some(item) => match getNumber(orderJson, "qty") {
      Some(qty) => match getNumber(orderJson, "price") {
        Some(price) => [{item: item, total: qty * price}],
        None => [] -- Price not found or not a number, return empty list
      },
      None => [] -- Qty not found or not a number, return empty list
    },
    None => [] -- Item not found or not a string, return empty list
  }

-- Pure predicate function to filter orders with total > 5.00
pure func isQualifyingOrder(order: OrderInfo) -> bool =
  order.total > 5.00

-- Effectful function to print a single order
func printOrder(order: OrderInfo) -> () ! {IO} =
  println(order.item ++ ": " ++ show(order.total))

-- Main function to orchestrate the process
export func main() -> () ! {IO} {
  let ordersJsonString = "[{\"id\":1,\"item\":\"apple\",\"qty\":5,\"price\":1.50},{\"id\":2,\"item\":\"banana\",\"qty\":3,\"price\":0.75},{\"id\":3,\"item\":\"orange\",\"qty\":8,\"price\":2.00}]";

  -- 1. Parse the JSON string
  match decode(ordersJsonString) {
    Ok(parsedJson) => {
      -- Ensure the parsed JSON is an array
      match asArray(parsedJson) {
        Some(jsonOrders) => {
          -- 2. Compute the total cost for each order and filter out invalid ones
          -- map applies parseAndCalculateForFlatMap to each Json order, resulting in [[OrderInfo]]
          let list_of_lists_of_orders = map(parseAndCalculateForFlatMap, jsonOrders);
          -- flatMap then flattens this list of lists into a single list of OrderInfo
          let validOrders = flatMap(\listElem. listElem, list_of_lists_of_orders);

          -- 3. Filter to keep only orders with total > 5.00
          let qualifyingOrders = filter(isQualifyingOrder, validOrders);

          -- 4. Print the item name and total for each qualifying order
          forEachE(printOrder, qualifyingOrders)
        },
        None => println("Error: Parsed JSON is not an array.")
      }
    },
    Err(msg) => println("Error parsing JSON: " ++ msg)
  }
}

