from dataclasses import dataclass
from typing import Union


@dataclass
class TVar:
    name: str


@dataclass
class TLam:
    var: str
    body: "Term"


@dataclass
class TApp:
    func: "Term"
    arg: "Term"


Term = Union[TVar, TLam, TApp]


def subst(term: Term, var: str, replacement: Term) -> Term:
    if isinstance(term, TVar):
        return replacement if term.name == var else term
    elif isinstance(term, TLam):
        if term.var == var:
            return term
        return TLam(term.var, subst(term.body, var, replacement))
    elif isinstance(term, TApp):
        return TApp(subst(term.func, var, replacement), subst(term.arg, var, replacement))


def eval(term: Term) -> Term:
    if isinstance(term, TVar):
        return term
    elif isinstance(term, TLam):
        return term
    elif isinstance(term, TApp):
        f = eval(term.func)
        arg = eval(term.arg)
        if isinstance(f, TLam):
            return eval(subst(f.body, f.var, arg))
        return TApp(f, arg)


def term_to_str(term: Term) -> str:
    if isinstance(term, TVar):
        return term.name
    elif isinstance(term, TLam):
        return f"λ{term.var}.{term_to_str(term.body)}"
    elif isinstance(term, TApp):
        return f"({term_to_str(term.func)} {term_to_str(term.arg)})"


def main():
    expr = TApp(TApp(TLam("x", TLam("y", TVar("x"))), TVar("1")), TVar("2"))
    result = eval(expr)
    print(term_to_str(result))


if __name__ == "__main__":
    main()

