pure func getLevel(line: string) -> string {
  let parts = split(line, " ");
  match parts {
    _ :: _ :: _ :: level :: _ => level,
    _ => ""
  }
}

pure func countLevel(lines: [string], level: string) -> int =
  listLength(filter(func(line: string) -> bool { getLevel(line) == level }, lines))

pure func extractUser(line: string) -> string {
  let level = getLevel(line);
  if level == "INFO" then {
    let msg = extractMessage(line);
    if contains(msg, "logged in:") then {
      let idx = find(msg, "logged in:");
      let after = substring(msg, idx + 11, length(msg));
      trim(after)
    } else if contains(msg, "logged out:") then {
      let idx = find(msg, "logged out:");
      let after = substring(msg, idx + 12, length(msg));
      trim(after)
    } else ""
  } else ""
}

pure func extractMessage(line: string) -> string {
  let parts = split(line, " ");
  match parts {
    _ :: _ :: _ :: _ :: rest => join(" ", rest),
    _ => ""
  }
}

pure func addUnique(users: [string], user: string) -> [string] =
  if user == "" then users
  else if containsStr(users, user) then users
  else users ++ [user]

pure func containsStr(xs: [string], s: string) -> bool =
  match xs {
    [] => false,
    x :: rest => if x == s then true else containsStr(rest, s)
  }

pure func collectUsers(lines: [string]) -> [string] =
  foldl(func(acc: [string], line: string) -> [string] {
    addUnique(acc, extractUser(line))
  }, [], lines)

