module benchmark/solution

export type Color = Red | Black
export type RBTree = Empty | Node(Color, RBTree, int, RBTree)

-- Balance function that fixes red-red violations
pure func balance(color: Color, left: RBTree, value: int, right: RBTree) -> RBTree =
  match color {
    Black => match left {
      -- Left-left case: Red(Red(a, x, b), y, c) => Red(Black(a, x, b), y, Black(c, z, d))
      Node(Red, Node(Red, a, x, b), y, c) =>
        Node(Red, Node(Black, a, x, b), y, Node(Black, c, value, right)),
      -- Left-right case: Red(a, x, Red(b, y, c)) => Red(Black(a, x, b), y, Black(c, z, d))
      Node(Red, a, x, Node(Red, b, y, c)) =>
        Node(Red, Node(Black, a, x, b), y, Node(Black, c, value, right)),
      _ => match right {
        -- Right-left case: Red(a, x, Red(b, y, c)) => Red(Black(a, x, b), y, Black(c, z, d))
        Node(Red, Node(Red, b, y, c), z, d) =>
          Node(Red, Node(Black, left, value, b), y, Node(Black, c, z, d)),
        -- Right-right case: Red(a, x, Red(b, y, c)) => Red(Black(a, x, b), y, Black(c, z, d))
        Node(Red, b, y, Node(Red, c, z, d)) =>
          Node(Red, Node(Black, left, value, b), y, Node(Black, c, z, d)),
        _ => Node(Black, left, value, right)
      }
    },
    Red => Node(Red, left, value, right)
  }

-- Insert helper that returns the tree and whether the root is red
func insertHelper(x: int, tree: RBTree) -> RBTree =
  match tree {
    Empty => Node(Red, Empty, x, Empty),
    Node(color, left, value, right) =>
      if x < value then
        balance(color, insertHelper(x, left), value, right)
      else if x > value then
        balance(color, left, value, insertHelper(x, right))
      else
        tree
  }

-- Insert function that ensures root is black
export func insert(x: int, tree: RBTree) -> RBTree =
  match insertHelper(x, tree) {
    Node(_, left, value, right) => Node(Black, left, value, right),
    Empty => Empty
  }

-- Inorder traversal to get sorted values
export func inorder(tree: RBTree) -> [int] =
  match tree {
    Empty => [],
    Node(_, left, value, right) => inorder(left) ++ [value] ++ inorder(right)
  }

-- Build tree by inserting values
func buildTree(values: [int], tree: RBTree) -> RBTree =
  match values {
    [] => tree,
    x :: rest => buildTree(rest, insert(x, tree))
  }

export func main() -> () ! {IO} {
  let values = [7, 3, 18, 10, 22, 8, 11, 26];
  let tree = buildTree(values, Empty);
  let sorted = inorder(tree);
  println(show(sorted))
}

