from enum import Enum, auto


class Color(Enum):
    Red = auto()
    Black = auto()


class Empty:
    pass


class Node:
    def __init__(self, color, left, value, right):
        self.color = color
        self.left = left
        self.value = value
        self.right = right


EMPTY = Empty()


def balance(color, left, value, right):
    if color == Color.Black:
        # Left-Left case
        if (isinstance(left, Node) and left.color == Color.Red and
                isinstance(left.left, Node) and left.left.color == Color.Red):
            a, x, b = left.left.left, left.left.value, left.left.right
            y, c, z, d = left.value, left.right, value, right
            return Node(Color.Red, Node(Color.Black, a, x, b), y, Node(Color.Black, c, z, d))
        # Left-Right case
        if (isinstance(left, Node) and left.color == Color.Red and
                isinstance(left.right, Node) and left.right.color == Color.Red):
            a, x, b = left.left, left.value, left.right.left
            y, c, z, d = left.right.value, left.right.right, value, right
            return Node(Color.Red, Node(Color.Black, a, x, b), y, Node(Color.Black, c, z, d))
        # Right-Left case
        if (isinstance(right, Node) and right.color == Color.Red and
                isinstance(right.left, Node) and right.left.color == Color.Red):
            a, x, b = left, value, right.left.left
            y, c, z, d = right.left.value, right.left.right, right.value, right.right
            return Node(Color.Red, Node(Color.Black, a, x, b), y, Node(Color.Black, c, z, d))
        # Right-Right case
        if (isinstance(right, Node) and right.color == Color.Red and
                isinstance(right.right, Node) and right.right.color == Color.Red):
            a, x, b = left, value, right.left
            y, c, z, d = right.value, right.right.left, right.right.value, right.right.right
            return Node(Color.Red, Node(Color.Black, a, x, b), y, Node(Color.Black, c, z, d))
    return Node(color, left, value, right)


def _insert(x, tree):
    if isinstance(tree, Empty):
        return Node(Color.Red, EMPTY, x, EMPTY)
    if x < tree.value:
        return balance(tree.color, _insert(x, tree.left), tree.value, tree.right)
    elif x > tree.value:
        return balance(tree.color, tree.left, tree.value, _insert(x, tree.right))
    else:
        return tree


def insert(x, tree):
    result = _insert(x, tree)
    return Node(Color.Black, result.left, result.value, result.right)


def inorder(tree):
    if isinstance(tree, Empty):
        return []
    return inorder(tree.left) + [tree.value] + inorder(tree.right)


def main():
    values = [7, 3, 18, 10, 22, 8, 11, 26]
    tree = EMPTY
    for v in values:
        tree = insert(v, tree)
    print(inorder(tree))


