    Mul(Const(0), _) => Const(0),
    Mul(_, Const(0)) => Const(0),
    Mul(Const(1), e) => simplify(e),
    Mul(e, Const(1)) => simplify(e),
    Mul(f, g) => Mul(simplify(f), simplify(g)),
