    left: "Expr"
    right: "Expr"


Expr = Union[Const, Var, Add, Mul]


def diff(expr: Expr, var: str) -> Expr:
    if isinstance(expr, Const):
        return Const(0)
    elif isinstance(expr, Var):
        return Const(1) if expr.name == var else Const(0)
    elif isinstance(expr, Add):
        return Add(diff(expr.left, var), diff(expr.right, var))
    elif isinstance(expr, Mul):
        return Add(Mul(expr.left, diff(expr.right, var)), Mul(expr.right, diff(expr.left, var)))


def simplify(expr: Expr) -> Expr:
    if isinstance(expr, (Const, Var)):
        return expr
    elif isinstance(expr, Add):
        left = simplify(expr.left)
        right = simplify(expr.right)
        if isinstance(left, Const) and left.value == 0:
            return right
        if isinstance(right, Const) and right.value == 0:
            return left
        return Add(left, right)
    elif isinstance(expr, Mul):
        left = simplify(expr.left)
        right = simplify(expr.right)
        if isinstance(left, Const) and left.value == 0:
            return Const(0)
        if isinstance(right, Const) and right.value == 0:
            return Const(0)
        if isinstance(left, Const) and left.value == 1:
            return right
        if isinstance(right, Const) and right.value == 1:
            return left
        return Mul(left, right)


