module benchmark/solution

type Type = TVar(string) | TInt | TBool | TFunc(Type, Type)

type Subst = [(string, Type)]

type Result = Success(Subst) | Failure(string)

pure func lookup(name: string, subst: Subst) -> Type =
  match subst {
    [] => TVar(name),
    (n, t) :: rest => if n == name then t else lookup(name, rest)
  }

pure func apply(subst: Subst, t: Type) -> Type =
  match t {
    TVar(name) => lookup(name, subst),
    TInt => TInt,
    TBool => TBool,
    TFunc(arg, res) => TFunc(apply(subst, arg), apply(subst, res))
  }

pure func compose(s1: Subst, s2: Subst) -> Subst =
  match s2 {
    [] => s1,
    (n, t) :: rest => (n, apply(s1, t)) :: compose(s1, rest)
  }

pure func unify(t1: Type, t2: Type) -> Result =
  match (t1, t2) {
    (TInt, TInt) => Success([]),
    (TBool, TBool) => Success([]),
    (TVar(a), t) => Success([(a, t)]),
    (t, TVar(a)) => Success([(a, t)]),
    (TFunc(a1, r1), TFunc(a2, r2)) =>
      match unify(a1, a2) {
        Failure(msg) => Failure(msg),
        Success(s1) => {
          let r1_sub = apply(s1, r1);
          let r2_sub = apply(s1, r2);
          match unify(r1_sub, r2_sub) {
            Failure(msg) => Failure(msg),
            Success(s2) => Success(compose(s2, s1))
          }
        }
      },
    _ => Failure("Cannot unify")
  }

pure func showType(t: Type) -> string =
  match t {
    TVar(name) => name,
    TInt => "TInt",
    TBool => "TBool",
    TFunc(arg, res) => "(" ++ showType(arg) ++ " -> " ++ showType(res) ++ ")"
  }

pure func printSubst(subst: Subst) -> () ! {IO} =
  match subst {
    [] => (),
    (name, t) :: rest => {
      println(name ++ " = " ++ showType(t));
      printSubst(rest)
    }
  }

export func main() -> () ! {IO} {
  let t1 = TFunc(TVar("a"), TInt);
  let t2 = TFunc(TBool, TVar("b"));
  match unify(t1, t2) {
    Success(subst) => printSubst(subst),
    Failure(msg) => println(msg)
  }
}

