from dataclasses import dataclass
from typing import Union, List, Tuple, Optional


@dataclass(frozen=True)
class TVar:
    name: str


@dataclass(frozen=True)
class TInt:
    pass


@dataclass(frozen=True)
class TBool:
    pass


@dataclass(frozen=True)
class TFunc:
    arg: 'Type'
    result: 'Type'


Type = Union[TVar, TInt, TBool, TFunc]
Subst = List[Tuple[str, Type]]


def apply(subst: Subst, t: Type) -> Type:
    if isinstance(t, TVar):
        for name, typ in subst:
            if name == t.name:
                return apply(subst, typ)
        return t
    elif isinstance(t, TFunc):
        return TFunc(apply(subst, t.arg), apply(subst, t.result))
    else:
        return t


def unify(t1: Type, t2: Type) -> Optional[Subst]:
    if isinstance(t1, TInt) and isinstance(t2, TInt):
        return []
    elif isinstance(t1, TBool) and isinstance(t2, TBool):
        return []
    elif isinstance(t1, TVar):
        return [(t1.name, t2)]
    elif isinstance(t2, TVar):
        return [(t2.name, t1)]
    elif isinstance(t1, TFunc) and isinstance(t2, TFunc):
        s1 = unify(t1.arg, t2.arg)
        if s1 is None:
            return None
        s2 = unify(apply(s1, t1.result), apply(s1, t2.result))
        if s2 is None:
            return None
        return s1 + s2
    else:
        return None


def type_to_str(t: Type) -> str:
    if isinstance(t, TVar):
        return f"TVar({t.name})"
    elif isinstance(t, TInt):
        return "TInt"
    elif isinstance(t, TBool):
        return "TBool"
    elif isinstance(t, TFunc):
        return f"TFunc({type_to_str(t.arg)}, {type_to_str(t.result)})"


def main():
    t1 = TFunc(TVar("a"), TInt())
    t2 = TFunc(TBool(), TVar("b"))
    subst = unify(t1, t2)
    if subst is not None:
        for name, typ in subst:
            print(f"{name} = {type_to_str(typ)}")


if __name__ == "__main__":
    main()
